<<IMG_118>>
\caption{The charge density associated with the occupied part of the metallic band in KC<<MATH_INLINE_258>>H<<MATH_INLINE_259>> at 50~GPa. (a) Isosurface with an isovalue of 0.005~<<MATH_INLINE_260>>. (b) Two-dimensional contour plot that cuts along the (1,0,1) plane colored from blue (0.000016~<<MATH_INLINE_261>>) to red (0.009~<<MATH_INLINE_262>>).}
    <<CMD_521>>
    \end{center}
\end{figure*}
